 static IEnumerable<T> All<T>(DependencyObject r)where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(r);i++){var c=VisualTreeHelper.GetChild(r,i);if(c is T)yield return (T)c;foreach(var x in All<T>(c))yield return x;}}
 static void Pump(){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);}static void Wait(Func<bool> done){var end=DateTime.UtcNow.AddSeconds(25);while(!done()&&DateTime.UtcNow<end){Pump();Thread.Sleep(5);}if(!done())throw new Exception("Timeout");}static void Finish(Task task){Wait(()=>task.IsCompleted);task.GetAwaiter().GetResult();}static void Click(Button b){b.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Pump();}static void Page(string n){Call("Page",n);Pump();main.UpdateLayout();}static string[] Nav(){return ((StackPanel)Get("navigation")).Children.OfType<Button>().Select(b=>Convert.ToString(b.Content)).ToArray();}static int Port(){var l=new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,0);l.Start();int port=((System.Net.IPEndPoint)l.LocalEndpoint).Port;l.Stop();return port;}
