  Check(Nav().SequenceEqual(new[]{"Серверы","Обновления","Конструктор"})&&(string)Get("current")=="Серверы","simple mode removes home and navigates directly to servers");Check(core.Running&&core.StartGeneration==generation,"switching presentation mode does not restart active network engine");
  string requested="У меня есть VPN и я в рот ебал сложные настройки";var caption=(TextBlock)Get("interfaceCaption");Check(caption.Text==requested&&caption.TextWrapping==TextWrapping.Wrap&&caption.ActualHeight<=44,"full requested mode name visibly rendered, not shortened or tooltip-only");
  Check(All<Button>(main).Any(b=>b.Name=="serverConnectButton")&&!All<Button>(main).Any(b=>b.Name=="serversSection1"),"connection button moved into servers and WARP tab removed");var grid=All<DataGrid>(main).Single(g=>g.Name=="serverGrid");var power=All<Button>(main).Single(b=>b.Name=="serverConnectButton");Check(power.TranslatePoint(new Point(0,power.ActualHeight),main).Y<grid.TranslatePoint(new Point(0,0),main).Y,"connection controls are above server list");Check(grid.Items.Count==1,"WARP profile is excluded from simple VPN server list");Save(main,"servers-simple-1050");
  Click(power);Wait(()=>!core.Running&&!(bool)Get("busy"));Check(!session.State.VpnEnabled,"moved connection control stops actual local core");Click(power);Wait(()=>core.Running&&!(bool)Get("busy"));Check(session.State.VpnEnabled,"moved connection control starts actual local proxy core");Finish(Task.Run(()=>core.Stop()));
  Page("Главная");Check((string)Get("current")=="Серверы","old Home history entry redirects to servers");Page("Конструктор");Check(!All<DataGrid>(main).Any()&&All<Button>(main).Any(b=>b.Name=="simpleThroughPresets")&&All<Button>(main).Any(b=>b.Name=="simpleDirectPresets"),"constructor uses two old-pattern multiselect blocks, not a table");
