  Check(Convert.ToString(All<Button>(main).Single(b=>b.Name=="simpleThroughPresets").Content).Contains("2")&&!session.State.Lists.Any(r=>r.BuiltinPreset=="simple-constructor:proxy"),"selection chips update without applying connection settings prematurely");
