  main.Width=1366;main.Height=865;Page("Серверы");Check(All<DataGrid>(main).Single(g=>g.Name=="serverGrid").ActualHeight>100,"servers remain usable with relocated controls at large size");Save(main,"servers-simple-1366");Finish((Task)Call("ChangeInterfaceMode",0));Page("Серверы");Check(All<Button>(main).Any(b=>b.Name=="serversSection1")&&session.State.Servers.Any(n=>n.Id==warp.Id),"standard mode retains WARP and its profiles");Finish((Task)Call("ChangeInterfaceMode",1));Call("RequestExit");Wait(()=>(bool)Get("closing")&&!main.IsVisible);Open(root);Check(session.State.InterfaceMode==1&&(string)Get("current")=="Серверы"&&!Nav().Contains("Главная"),"restart restores own-VPN mode directly to servers");Call("RequestExit");Wait(()=>(bool)Get("closing")&&!main.IsVisible);app.Shutdown();Console.WriteLine("RESULT "+count+" checks PASS; no external provider, TUN or WARP registration used");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);if(session!=null)session.Core.Stop();if(main!=null)Call("RequestExit");return 1;}}
